

public class Main {
    public static void main(String[] args) {

        System.out.println(isSubsequence("leeeeetcode", ""));
    }

    public static boolean isSubsequence(String s, String t) {
        boolean isSubsequence = false;

        if (s.length() == 0) {
            return true;
        }


        int lastMatch = 0;

        int position = 0;
        int sPos = 0;
        while (position < t.length() && sPos < s.length()) {

            if (t.charAt(position) == s.charAt(sPos) && lastMatch <= position) {
                if (sPos == s.length() - 1) {
                    isSubsequence = true;
                    break;
                }
                lastMatch = position;
                sPos++;
                position++;
            } else {
                position++;
            }
        }

        System.out.println("Sequence: " + isSubsequence);
        return isSubsequence;
    }
}